import DialogModal from "@/core/components/primitives/dialog-modal/dialog-modal";
import { DailyInformation } from "./daily-information/daily-information";
import VariantList from "./variant-list/variant-list";
import { IContentfulLink } from "@/core/types/contentful-types";
