import { useStepWarning } from "../../step-warning/step-warning";
import {
  ProductWithTicketsForQuantity,
  PurchaseFlowWithTicketsForQuantity,
} from "@/core/helpers/group-admission-helper";
import { ButtonRow } from "../../components/button-row";
import {
  allCalendarDataHasPriceLevelData,
  computedPriceMap,
  dayState,
} from "@/core/components/primitives/calendar/calendar-helpers";
import { withPricelevels } from "@/core/components/primitives/calendar/modifiers/usePriceLevels";
import { withHasEvents } from "@/core/components/primitives/calendar/modifiers/withHasEvents";
import { withIsSoldOutExceptForEventDays } from "@/core/components/primitives/calendar/modifiers/withIsSoldOut";
import { withMarking } from "@/core/components/primitives/calendar/modifiers/withMarking";
import { LabelKey } from "@/core/labels/i18n";
import getStyleOverrides, { GroupAdmissionCustomColorsProps } from "./calendar-color-overrides";
import { OpeningHoursItem } from "@parksandresorts/webapiproxy-types";

type InformationModal = ({ type: "DATE"; value: Date } | { type: "VARIANT"; value: EntryVariant }) & {
  headingText: string;
  bodyText: string;
  confirmChange: string;
  contentfulLabelIds: {
    headingText: string;
    bodyText: string;
    confirmChange: string;
  };
};

type GroupAdmissionCalendarProps = {
  showConcertsInCalendar: boolean;
  selectedDateOpeningHours: Pick<OpeningHoursItem, "opens" | "closing"> | null;
  selectedDateProducts: Array<Product>;
  selectedDates: Map<string, VisitDate>;
  selectedMonth: Date;
  selectedVariant: EntryVariant | null;
  variantsForSelectedDate: Array<string>;
  variants: Record<string, EntryVariant>;
  calendarData: Array<PurchaseFlowDate>;
  quantity: GroupAdmissionState["quantity"];
  visitorCategories: Map<VisitorCategory["id"], VisitorCategory>;
  dailyInformationLink?: IContentfulLink;
  hideParkOpeningTimes: boolean;
  isNextStepCompleted: boolean;
  stepWrapperRef: HTMLElement;
  isActive: boolean;
  soldOutEventDateContent: any;
  eventContainerLink?: IContentfulLink;
  priceLevelPresenterText?: string;
  hideVariant?: boolean;
  customColors?: GroupAdmissionCustomColorsProps;
  priceLevelsWithMarking?: Array<number>;
} & StepProps;

const getDailyInformationForDate = (
  selectedDates: Map<string, VisitDate>,
  calendarDataForSelectedQuantities: Array<PurchaseFlowWithTicketsForQuantity>,
) => {
  const [selectedDate] = [...selectedDates.values()];
  const [selectedDateInCalendarData] = calendarDataForSelectedQuantities.filter((date) =>
    DateHelper.isEqualYYYYMMDD(selectedDate.date, date.date),
  );

  const dailyInformationForDate: DailyInformationData = {
    opens: selectedDateInCalendarData.opens,
    closing: selectedDateInCalendarData.closing,
    date: selectedDateInCalendarData.date,
    anyDateSlotQuantityLeft: GroupAdmissionHelper.atLeastOneVariantHasTicketsLeft(selectedDateInCalendarData.products),
    shows: selectedDateInCalendarData.shows,
    textBlocks: selectedDateInCalendarData.textBlocks,
  };

  return dailyInformationForDate;
};

const tryScrollToCalendar = (calendarRef: MutableRefObject<any>) => {
  const calendarOffsetTop = calendarRef?.current?.offsetTop;
  const windowOffset = window.scrollY;

  if (windowOffset < calendarOffsetTop) {
    animatedScrollTo(calendarRef.current, { verticalOffset: -54, speed: 1000 });
  }
};

export type VariantSummary = {
  totalPrice: number;
  hasTicketsLeft: boolean;
  priceDifference: number;
};

const calculateVariantSummary = (
  variantId: string,
  selectedDateProducts: Array<ProductWithTicketsForQuantity>,
  quantity: GroupAdmissionState["quantity"],
): VariantSummary => {
  const productsForVariant = selectedDateProducts.filter(
    (product) => (product?.productMetadata?.entryVariant ?? null) === variantId,
  );

  if (productsForVariant.every((product) => product.ticketsForQuantity)) {
    return productsForVariant.reduce<VariantSummary>(
      (summary, product) => {
        const quantityForCategory = quantity.get(product?.productMetadata?.visitorCategory);
        if (typeof quantityForCategory === "number" && quantityForCategory > 0) {
          summary.totalPrice += product.price * quantityForCategory;
          summary.hasTicketsLeft = (product.dateSlot?.quantity ?? 0) >= quantityForCategory;
        }
        return summary;
      },
      { totalPrice: 0, hasTicketsLeft: false, priceDifference: 0 },
    );
  }
  return { totalPrice: 0, hasTicketsLeft: false, priceDifference: 0 };
};

const GroupAdmissionCalendar = ({
  onClickBack,
  stepIndex,
  dispatch,
  selectedDateOpeningHours,
  selectedMonth,
  selectedVariant,
  variantsForSelectedDate,
  selectedDates,
  variants,
  calendarData,
  selectedDateProducts,
  quantity,
  visitorCategories,
  dailyInformationLink,
  hideParkOpeningTimes,
  isNextStepCompleted,
  stepWrapperRef,
  isActive,
  soldOutEventDateContent,
  eventContainerLink,
  hideVariant,
  customColors,
  priceLevelsWithMarking,
}: GroupAdmissionCalendarProps) => {
  const startDate = DateHelper.getModifiedDateByMonth(TodayHelper.getNow(), 0);

  const calendarRef = useRef();
  const [showCalendarWarning, setShowCalendarWarning] = useState<{
    title: LabelKey;
    bodyText: LabelKey;
  }>(null);
  const [showVariantWarning, setShowVariantWarning] = useState(false);
  const [informationModalProps, setInformationModalProps] = useState<InformationModal>(null);
  const [dailyInformationForDate, setDailyInformationForDate] = useState<DailyInformationData>(null);
  const [focusRef, setFocus] = useFocus<HTMLDivElement>();

  const { t } = useTranslation();

  const styleOverrides = getStyleOverrides(customColors);

  // Filter out visitor categories with `hideInPriceLevelPresenter`: true
  const visibleVisitorCategories = useMemo(() => {
    return new Map([...visitorCategories.entries()].filter(([, category]) => !category.hideInPriceLevelPresenter));
  }, [visitorCategories]);

  const variantWarningLabel = useMemo(() => {
    const isMultipleNumberOfDays = Object.values(variants).some((variant) => variant.numberOfDays > 1);

    return isMultipleNumberOfDays
      ? "calendarStepCalendarWarningVariantBodyTextMultipleDays"
      : "calendarStepCalendarWarningVariantBodyTextSingleDay";
  }, [variants]);

  const { scrollAndFocusOnWarning: scrollAndFocusOnCalendarWarning, StepWarning: CalendarStepWarning } = useStepWarning(
    { ...showCalendarWarning },
  );
  const { scrollAndFocusOnWarning: scrollAndFocusOnVariantWarning, StepWarning: VariantStepWarning } = useStepWarning({
    title: "calendarStepCalendarWarningVariantTitle",
    bodyText: variantWarningLabel,
    verticalOffset: -144,
  });

  const calendarDataForSelectedQuantities = useMemo(
    () =>
      calendarData.map((purchaseFlowDate) => {
        const visitorCategorySet = new Set<VisitorCategory>(); // Track visitor categories for each date
        const visitorCategoryQuantityMap: GroupAdmissionState["quantity"] = new Map(); // Track total quantity for each visitor category

        // Calculate total quantity of tickets in stock for each visitor category
        for (const product of purchaseFlowDate.products) {
          const productVisitorCategory = product.productMetadata.visitorCategory;
          const totalQuantityForCategory = visitorCategoryQuantityMap.get(productVisitorCategory) || 0;
          visitorCategoryQuantityMap.set(
            productVisitorCategory,
            totalQuantityForCategory + (product.dateSlot?.quantity || 0),
          );

          // Add visitor category to Set (if visible)
          const visitorCategory = visibleVisitorCategories.get(productVisitorCategory);
          if (visitorCategory) {
            visitorCategorySet.add(visitorCategory);
          }
        }

        // Use map-filter to determine if each product has enough tickets in stock
        const reducedProductsForDate = purchaseFlowDate.products
          .map((product) => {
            const productVisitorCategory = product.productMetadata.visitorCategory;
            const quantityForCategory = quantity.get(productVisitorCategory);

            if (typeof quantityForCategory === "number" && quantityForCategory > 0) {
              const ticketsForQuantity = hideVariant
                ? visitorCategoryQuantityMap.get(productVisitorCategory) >= quantityForCategory
                : product.dateSlot && product.dateSlot.quantity >= quantityForCategory;
              return { ...product, ticketsForQuantity } satisfies ProductWithTicketsForQuantity;
            }
            return null;
          })
          .filter(isTruthy);

        return { ...purchaseFlowDate, products: reducedProductsForDate, visitorCategories: [...visitorCategorySet] };
      }),
    [calendarData, quantity, visibleVisitorCategories, hideVariant],
  );

  const selectedVisitorCategories = [...quantity]
    .filter(([_category, count]) => count > 0 && visibleVisitorCategories.has(_category))
    .map(([category]) => category);

  const { uniqueProductTypes, uniqueVisitorCategories } = createPricePresentationFromCalendarData(
    selectedVisitorCategories,
    calendarDataForSelectedQuantities,
  );

  const isProductTypeToggler = uniqueProductTypes.length > 1;
  const toggleOptions = isProductTypeToggler ? uniqueProductTypes : uniqueVisitorCategories;

  // We track lastSelectedActivePricePresentationValue, but then we check if it is in the list of unique product types or visitor categories
  // If it is not, we set it to the first value in the list
  // This way, we do not show incorrect prices if a user changes the presentation value and the last selected value is not in the new list
  // This can happen if the user first selects 2 adults and 2 kids, goes to the calendar, selects price presentation for kids, and then goes back and changes the quantity to 2 adults 0 kids
  const [lastSelectedActivePricePresentationValue, setActivePricePresentationValue] = useState<
    ProductType | VisitorCategory["id"]
  >(null);
  const activePricePresentationValue =
    [...uniqueProductTypes, ...uniqueVisitorCategories].find(
      (value) => value === lastSelectedActivePricePresentationValue,
    ) ?? toggleOptions[0];

  const calendarFooterInfoString =
    activePricePresentationValue && createCalendarFooterPricePresentation(activePricePresentationValue, t);

  const selectedDatesArray = useMemo(() => [...selectedDates.values()].map((date) => date.date), [selectedDates]);

  const variantSummary = useMemo(() => {
    const [selectedDate] = selectedDatesArray;
    const selectedPurchaseFlowDate =
      selectedDate &&
      calendarDataForSelectedQuantities.find((date) => DateHelper.isEqualYYYYMMDD(date.date, selectedDate));
    const summary = new Map<string, VariantSummary>();

    for (const variant of variantsForSelectedDate) {
      summary.set(
        variant,
        calculateVariantSummary(variant, selectedPurchaseFlowDate ? selectedPurchaseFlowDate.products : [], quantity),
      );
    }
    const summaryCopy = new Map<string, VariantSummary>(summary);
    for (const [variantId, variantSummary] of summaryCopy) {
      const variantSummaryCopy = { ...variantSummary };

      // Hitta första variant som inte är jag
      const firstOtherVariantId = [...summary.keys()].find((otherVariantId) => otherVariantId !== variantId);
      if (firstOtherVariantId) {
        const otherSummary = summary.get(firstOtherVariantId);
        variantSummaryCopy.priceDifference = variantSummary.totalPrice - otherSummary.totalPrice;
        summary.set(variantId, variantSummaryCopy);
      }
    }
    return summary;
  }, [selectedDatesArray, variantsForSelectedDate, calendarDataForSelectedQuantities, quantity]);

  const isSelectedVariantAvailable = useMemo(() => {
    return selectedVariant && variantSummary.has(selectedVariant.id)
      ? variantSummary.get(selectedVariant.id).hasTicketsLeft
      : false;
  }, [selectedVariant, variantSummary]);

  useEffect(() => {
    !isActive && setShowCalendarWarning(null);
  }, [isActive]);

  useEffect(() => {
    if (selectedDates.size === 0 || !isNonEmptyArray(calendarDataForSelectedQuantities)) {
      return;
    }

    const dailyInformationForDate = getDailyInformationForDate(selectedDates, calendarDataForSelectedQuantities);
    setDailyInformationForDate(dailyInformationForDate);

    if (selectedDates && isActive === true) {
      tryScrollToCalendar(calendarRef);
      return;
    }
  }, [selectedDates, calendarDataForSelectedQuantities, isActive]);

  const onClickDate = (selectedDate: Date, overrideClick?: boolean) => {
    const calData = calendarDataForSelectedQuantities.find((d) => DateHelper.isEqualYYYYMMDD(selectedDate, d.date));
    if (isNextStepCompleted && !overrideClick) {
      return setInformationModalProps({
        type: "DATE",
        headingText: t("calendarStepDialogChangeDateHeading"),
        bodyText: t("calendarStepDialogChangeDateBodyText"),
        confirmChange: t("calendarStepDialogConfirmChangeDate"),
        contentfulLabelIds: {
          headingText: "calendarStepDialogChangeDateHeading",
          bodyText: "calendarStepDialogChangeDateBodyText",
          confirmChange: "calendarStepDialogConfirmChangeDate",
        },
        value: selectedDate,
      });
    }
    if (overrideClick) {
      setFocus();
    }
    setInformationModalProps(null);
    dispatch({
      type: ActionType.SELECT_DATE,
      payload: { ...calData, selectedDate, hideVariant: hideVariant ?? false },
    });
  };

  const onClickChangeMonth = (month: Date) => {
    dispatch({ type: ActionType.SELECT_MONTH, payload: { selectedMonth: month } });
  };

  const onClickVariant = (variant: EntryVariant, overrideClick?: boolean) => {
    if (variant.id === selectedVariant?.id) {
      return;
    }
    if (isNextStepCompleted && !overrideClick) {
      return setInformationModalProps({
        type: "VARIANT",
        headingText: t("calendarStepDialogChangeVariantHeading"),
        bodyText: t("calendarStepDialogChangeVariantBodyText"),
        confirmChange: t("calendarStepDialogConfirmChangeVariant"),
        contentfulLabelIds: {
          headingText: "calendarStepDialogChangeVariantHeading",
          bodyText: "calendarStepDialogChangeVariantBodyText",
          confirmChange: "calendarStepDialogConfirmChangeVariant",
        },
        value: variant,
      });
    }
    if (overrideClick) {
      setFocus();
    }
    setInformationModalProps(null);
    dispatch({ type: ActionType.SELECT_VARIANT, payload: { selectedVariant: variant } });
  };

  const onClickStepComplete = () => {
    const shouldShowVariantWarning =
      !hideVariant && selectedDates.size > 0 && (!selectedVariant || !isSelectedVariantAvailable);

    const shouldShowCalendarWarning = !selectedDates.size;

    const selectedDateInCalendarData = calendarDataForSelectedQuantities?.find((date) =>
      selectedDatesArray.some((selectedDate) => DateHelper.isEqualYYYYMMDD(selectedDate, date.date)),
    );

    const isDateNotAvailableWithVariants =
      !hideVariant &&
      selectedDateInCalendarData?.products.every(
        (product: Product & ProductWithTicketsForQuantity) => product.ticketsForQuantity === false,
      );

    const isDateNotAvailableWithQuantity =
      hideVariant &&
      selectedDateInCalendarData?.products.some(
        (product: Product & ProductWithTicketsForQuantity) => product.ticketsForQuantity === false,
      );

    if (isDateNotAvailableWithQuantity || isDateNotAvailableWithVariants) {
      setShowCalendarWarning({
        title: "calendarStepCalendarWarningNotAvailableTitle",
        bodyText: "calendarStepCalendarWarningNoDatePickedBodyText",
      });
      setShowVariantWarning(false);
      scrollAndFocusOnCalendarWarning();
      return;
    }

    if (shouldShowVariantWarning) {
      setShowVariantWarning(true);
      setShowCalendarWarning(null);
      scrollAndFocusOnVariantWarning();
      return;
    }

    if (shouldShowCalendarWarning) {
      setShowCalendarWarning({
        title: "calendarStepCalendarWarningNoDatePickedTitle",
        bodyText: "calendarStepCalendarWarningNoDatePickedBodyText",
      });
      setShowVariantWarning(false);
      scrollAndFocusOnCalendarWarning();
      return;
    }

    setShowCalendarWarning(null);
    setShowVariantWarning(false);
    GroupAdmissionHelper.scrollAndCompleteStep(stepWrapperRef, Step.SELECT_DATE, dispatch, true);
  };

  const handlePriceChange = (activeValue: ProductType | VisitorCategory["id"]) => {
    setActivePricePresentationValue(activeValue);
  };

  function closeDialog() {
    setFocus();
    setInformationModalProps(null);
  }

  const isPriceLevelCalendar = allCalendarDataHasPriceLevelData(calendarData);
  const endDate = calendarData?.at(-1)?.date ?? TodayHelper.getNow();

  const dayStates = dayState({
    isPriceLevelDate: isPriceLevelCalendar,
    calendarData: calendarDataForSelectedQuantities,
    priceLevelsWithMarking,
  });

  const priceLevels = withPricelevels(isPriceLevelCalendar, dayStates);
  const hasEvents = withHasEvents(dayStates);
  const isSoldOut = withIsSoldOutExceptForEventDays(dayStates);
  const showMarking = withMarking(dayStates);

  const priceMap = computedPriceMap({
    calendarData,
    activePricePresentationValue,
    variants,
  });

  return (
    <div ref={focusRef} tabIndex={-1} className={styles.wrapper}>
      <AnimatePresence mode="wait">{showCalendarWarning && <CalendarStepWarning />}</AnimatePresence>
      {isNonEmptyArray(calendarData) && (
        <PricePresentationControls
          toggleOptions={toggleOptions}
          visitorCategories={visibleVisitorCategories}
          activePricePresentationValue={activePricePresentationValue}
          onPriceChange={handlePriceChange}
        />
      )}
      <div ref={calendarRef}>
        <StepBackdrop>
          <div className={styles.calendarWrapper} style={styleOverrides}>
            <Calendar
              startDate={startDate}
              endDate={endDate}
              changedMonth={(month) => onClickChangeMonth(month)}
              currentDisplayedMonth={selectedMonth}
              changeDate={(clickedDate) => onClickDate(clickedDate)}
              selectedDate={selectedDatesArray}
              disabledDates={(d) => !dayStates.has(d)}
              showOutsideDays
              footerInfoString={calendarFooterInfoString}
              computedPriceMap={priceMap}
              hasPriceLevelsWithMarking={isNonEmptyArray(priceLevelsWithMarking)}
              modifiers={{
                ...priceLevels,
                ...hasEvents,
                ...isSoldOut,
                ...showMarking,
              }}
            />
          </div>
        </StepBackdrop>
        {selectedDates.size > 0 && (
          <motion.div
            key="variantList"
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "100%" }}
            exit={{ opacity: 0 }}
            transition={{
              height: { duration: 0.3 },
              opacity: { delay: 0.4, duration: 0.3, type: "tween" },
            }}
            className={styles.variantWrapper}
          >
            {dailyInformationForDate && (
              <DailyInformation
                information={dailyInformationForDate}
                dailyInformationLink={dailyInformationLink}
                hideParkOpeningTimes={hideParkOpeningTimes}
                soldOutEventDateContent={soldOutEventDateContent}
                eventContainerLink={eventContainerLink}
              />
            )}
            {!hideVariant && Object.keys(variants).length > 1 && (
              <div className={styles.variantWrapper}>
                {showVariantWarning && <VariantStepWarning />}
                <StepBackdrop>
                  <div className={styles.variantListWrapper}>
                    <h3
                      data-contentful-label-id="calendarStepVariantSelectionHeading"
                      className={`heading-xs ${styles.variantHeading}`}
                    >
                      {t("calendarStepVariantSelectionHeading")}
                    </h3>
                    <VariantList
                      variants={variants}
                      selectedVariant={selectedVariant?.id ?? null}
                      variantsForSelectedDate={variantsForSelectedDate}
                      selectedDateProducts={selectedDateProducts}
                      selectedDateOpeningHours={selectedDateOpeningHours}
                      onClickVariant={onClickVariant}
                      variantSummary={variantSummary}
                    />
                  </div>
                </StepBackdrop>
              </div>
            )}
          </motion.div>
        )}
        <ButtonRow
          stepIndex={stepIndex}
          onClickBack={onClickBack}
          onClickStepComplete={onClickStepComplete}
          nextTestId="calendar-next-button"
        />
      </div>
      <AnimatePresence>
        {informationModalProps && (
          <DialogModal
            headingText={informationModalProps.headingText}
            bodyText={informationModalProps.bodyText}
            primaryButtonText={informationModalProps.confirmChange}
            primaryButtonAction={() => {
              setFocus;
              informationModalProps.type === "DATE"
                ? onClickDate(informationModalProps.value, true)
                : onClickVariant(informationModalProps.value, true);
            }}
            secondaryButtonText={t("cancel")}
            contentfulLabelIds={{ ...informationModalProps.contentfulLabelIds, cancelChange: "cancel" }}
            secondaryButtonAction={closeDialog}
            onCloseFunction={closeDialog}
          />
        )}
      </AnimatePresence>
    </div>
  );
};

export default GroupAdmissionCalendar;
