import { DateHelper, GroupAdmissionHelper, isNonEmptyArray, productHasQuantity } from "@/core/helpers";
import { CalendarData, CalendarDayProps, ProductCalendarItem } from "./types/calendar-types";
import { DateMap } from "@/core/helpers/date-helper";
import { PurchaseFlowDate } from "@/core/types/state/group-admission/group-admission-types";
import { Matcher } from "react-day-picker";
import { Product, EntryVariant, VisitorCategory } from "@/core/types/services/purchase-flow-service-types";
import { ProductWithTicketsForQuantity } from "@/core/helpers/group-admission-helper";
import {
  PRODUCT_TYPE_PRICE_VISITOR_CATEGORY_VALUE,
  ProductType,
} from "@/core/components/blocks/group-admission/steps/calendar/price-presentation-controls/price-presentation-controls";

// Stolen from the react-day-picker-repo
// Source: https://github.com/gpbl/react-day-picker/blob/6fc2614dbcb7016ad0362385b44ea016039bc080/src/contexts/Modifiers/utils/matcherToArray.ts
export function matcherToArray(matcher: Matcher | Matcher[] | undefined): Matcher[] {
  if (Array.isArray(matcher)) {
    return [...matcher];
  } else if (matcher !== undefined) {
    return [matcher];
  }
  return [];
}

export function allCalendarDataHasPriceLevelData(calendarData: CalendarData) {
  return calendarData?.every(
    (item) =>
      (item as PurchaseFlowDate).products !== undefined && (item as PurchaseFlowDate).visitorCategories !== undefined,
  );
}

/**
 * Returns a DateMap with basic day state info:
 * - priceLevel: the lowest price level for the day.
 * - hasEvents, isSoldOut, showMarking: used for styling.
 */
export const dayState = ({
  isPriceLevelDate,
  calendarData,
  priceLevelsWithMarking,
}: Pick<CalendarDayProps, "isPriceLevelDate"> & {
  calendarData: CalendarData;
  priceLevelsWithMarking?: Array<number>;
}) =>
  new DateMap(
    calendarData.map((dayData) => {
      const products: Array<ProductCalendarItem | Product> | false = "products" in dayData && dayData.products;
      const allProductsSoldOut = isNonEmptyArray(products) && products.every((p) => "soldOut" in p && p.soldOut);
      const visitorCategories = "visitorCategories" in dayData && dayData.visitorCategories;
      const events = "shows" in dayData && dayData.shows;

      // TODO: these types needs to be improved on. The casts are not good.
      const priceLevel =
        products &&
        visitorCategories &&
        GroupAdmissionHelper.getLowestPriceLevel(products as Array<Product>, visitorCategories);
      const hasPriceLevelTicketsLeft =
        products &&
        isPriceLevelDate &&
        GroupAdmissionHelper.atLeastOneVariantHasTicketsLeft(products as Array<ProductWithTicketsForQuantity>);
      const hasProductsQuantity =
        products && !isPriceLevelDate && products.some((product) => productHasQuantity(product));

      const isSoldOut = (!hasPriceLevelTicketsLeft && !hasProductsQuantity) || allProductsSoldOut;
      const hasEvents = events && events.length > 0;
      const showMarking = isNonEmptyArray(priceLevelsWithMarking)
        ? priceLevelsWithMarking.includes(priceLevel as number)
        : false;

      return [DateHelper.toStringYYYYMMDD(dayData.date), { priceLevel, hasEvents, isSoldOut, showMarking }];
    }),
  );

/**
 * Computes the computedPrice for each day based on active toggler value & variants.
 * It first collects candidate products for the day and filters them based on whether
 * the active value is a product type or a visitor category.
 */
export const computedPriceMap = ({
  calendarData,
  activePricePresentationValue,
  variants,
}: {
  calendarData: CalendarData;
  activePricePresentationValue?: ProductType | VisitorCategory["id"];
  variants?: Record<string, EntryVariant>;
}) =>
  new DateMap<{ computedPrice: number | undefined }>(
    calendarData.map((dayData) => {
      const key = DateHelper.toStringYYYYMMDD(dayData.date);
      const products = "products" in dayData && dayData.products;
      const visitorCategories = "visitorCategories" in dayData && dayData.visitorCategories;

      // If any required value is missing, return undefined price.
      if (!(activePricePresentationValue && products && visitorCategories && variants)) {
        return [key, { computedPrice: undefined }];
      }

      // Map all candidate products with relevant info.
      const candidateProducts = (products as Array<Product>).map((product) => {
        const productType: ProductType = product.productMetadata?.numberOfJetPassIncluded > 0 ? "Jetpass" : "Entry";
        return {
          price: product.price,
          productVariant: product.productMetadata.entryVariant,
          productType,
          visitorCategory: product.productMetadata.visitorCategory,
        };
      });

      let validCandidates = [];

      // If active toggler is a product type, filter by matching productType and default visitor category.
      if (["Jetpass", "Entry"].includes(activePricePresentationValue as string)) {
        validCandidates = candidateProducts.filter(
          (p) =>
            p.productType === activePricePresentationValue &&
            p.visitorCategory === PRODUCT_TYPE_PRICE_VISITOR_CATEGORY_VALUE,
        );
      } else {
        // Otherwise, filter only by visitor category.
        validCandidates = candidateProducts.filter((p) => p.visitorCategory === activePricePresentationValue);
      }

      if (validCandidates.length === 0) {
        return [key, { computedPrice: undefined }];
      }

      // If there are multiple valid candidates, pick the one with the lowest sortIndex.
      const priceBySortIndex = validCandidates.reduce((acc, curr) => {
        if (
          acc.productVariant &&
          curr.productVariant &&
          variants[acc.productVariant].sortIndex > variants[curr.productVariant].sortIndex
        ) {
          return curr;
        }
        return acc;
      }).price;

      return [key, { computedPrice: priceBySortIndex }];
    }),
  );
