    //         <div className={styles.bottomSection}>
    //             <p className={`p_small ${styles.label}`}>{variant.id === 'TwoDays' ? labels.added : labels.total}</p>
    //             {variantSummary.hasTicketsLeft && (
    //                 <motion.p
