import { DateMap } from "@/core/helpers/date-helper";
import { range } from "lodash-es";
import { Matcher } from "react-day-picker";

export const withPricelevels = (
  isPriceLevelCalendar: boolean,
  dayInfo: DateMap<{ priceLevel: number | false }>,
): Record<string, Matcher> => {
  if (!isPriceLevelCalendar) return {};

  const levels = range(11);

  return Object.fromEntries(
    levels.map((level) => [
      `priceLevel${level}`,
      (day: Date) => {
        return dayInfo.get(day)?.priceLevel === level;
      },
    ]),
  );
};
