export type GroupAdmissionCustomColorsProps = {
  primaryPricingTextColor?: string;
  primaryPricingBackgroundColor?: string;
  primaryPricingTextColorHover?: string;
  primaryPricingBackgroundColorHover?: string;
  primaryPricingBackgroundColorSelected?: string;
  markedPricingTextColor?: string;
  markedPricingBackgroundColor?: string;
  markedPricingTextColorHover?: string;
  markedPricingBackgroundColorHover?: string;
  primaryPricingSelectedTextColor?: string;
  primaryPricingSelectedBorderColor?: string;
  primaryPricingSelectedDateMarkerTextColor?: string;
  primaryPricingSelectedDateMarkerBackgroundColor?: string;
};

type OverridableCssVariables =
  | "--component-calendar-available-date-color"
  | "--component-calendar-available-date-background-color"
  | "--component-calendar-available-date-hover-color"
  | "--component-calendar-available-date-hover-background-color"
  | "--component-calendar-selected-date-background-color"
  | "--component-calendar-available-date-marked-color"
  | "--component-calendar-available-date-marked-background-color"
  | "--component-calendar-available-date-marked-hover-color"
  | "--component-calendar-available-date-marked-hover-background-color"
  | "--component-calendar-selected-date-text-color"
  | "--component-calendar-selected-date-border-color"
  | "--component-calendar-selected-date-marker-text-color"
  | "--component-calendar-selected-date-marker-background-color";

type ColorOverridesKeys = keyof GroupAdmissionCustomColorsProps;

const overrideMapping = {
  primaryPricingTextColor: ["--component-calendar-available-date-color"],
  primaryPricingBackgroundColor: ["--component-calendar-available-date-background-color"],
  primaryPricingTextColorHover: ["--component-calendar-available-date-hover-color"],
  primaryPricingBackgroundColorHover: ["--component-calendar-available-date-hover-background-color"],
  primaryPricingBackgroundColorSelected: ["--component-calendar-selected-date-background-color"],
  markedPricingTextColor: ["--component-calendar-available-date-marked-color"],
  markedPricingBackgroundColor: ["--component-calendar-available-date-marked-background-color"],
  markedPricingTextColorHover: ["--component-calendar-available-date-marked-hover-color"],
  markedPricingBackgroundColorHover: ["--component-calendar-available-date-marked-hover-background-color"],
  primaryPricingSelectedTextColor: ["--component-calendar-selected-date-text-color"],
  primaryPricingSelectedBorderColor: ["--component-calendar-selected-date-border-color"],
  primaryPricingSelectedDateMarkerTextColor: ["--component-calendar-selected-date-marker-text-color"],
  primaryPricingSelectedDateMarkerBackgroundColor: ["--component-calendar-selected-date-marker-background-color"],
} satisfies Record<ColorOverridesKeys, Array<OverridableCssVariables>>;

const getStyleOverrides = (colorOverrides?: GroupAdmissionCustomColorsProps) => {
  if (!colorOverrides) return {};

  const listOfAllKeysOfColorOverrides = Object.keys(overrideMapping) as Array<ColorOverridesKeys>;

  // A type for the object of the css variables that can be overriden and their new values
  const styleOverrides = {} as Record<OverridableCssVariables, string>;
  for (const key of listOfAllKeysOfColorOverrides) {
    const overrideValue = colorOverrides[key];
    if (!overrideValue) continue;

    for (const cssVariable of overrideMapping[key]) {
      styleOverrides[cssVariable] = overrideValue;
    }
  }

  return styleOverrides as React.CSSProperties;
};

export default getStyleOverrides;
