// @ts-strict-ignore
import VariantListItem from "../variant-list-item/variant-list-item";
import { ENTRY_VARIANT, EntryVariant, Product } from "@/core/types/services/purchase-flow-service-types";
import { VariantSummary } from "../group-admission-calendar";
import StyledRadioButtons from "@/core/components/primitives/styled-radio-buttons/styled-radio-buttons";
import { RadioOption } from "@/core/components/primitives/radio-buttons/radio-buttons";
import { createDate, DateHelper, extract, sortIndexComparer } from "@/core/helpers";
import { OpeningHoursItem } from "@parksandresorts/webapiproxy-types";

export type VariantListProps = {
  variants: Record<string, EntryVariant>;
  variantsForSelectedDate: Array<string>;
  selectedVariant: (typeof ENTRY_VARIANT)[keyof typeof ENTRY_VARIANT];
  onClickVariant: CallableFunction;
  selectedDateProducts: Array<Product>;
  selectedDateOpeningHours: Pick<OpeningHoursItem, "opens" | "closing">;
  variantSummary: Map<string, VariantSummary>;
};

const hasTimePassed = (selectedDateProducts: Array<Product>, variantId: string) => {
  const productEntryVariant = selectedDateProducts.find((product) => {
    const productDate = createDate(product?.dateSlot?.date);
    const productEntryVariant = extract<string>(product, "productMetadata.entryVariant");
    return productEntryVariant == variantId && DateHelper.isToday(productDate);
  });

  const productLastTime = extract<string>(
    productEntryVariant,
    "productMetadata.timeLimits.lastRideTime",
    extract<string>(productEntryVariant, "productMetadata.timeLimits.lastEntryTime"),
  );

  return productLastTime && DateHelper.hasTimePassedToday(productLastTime);
};

const VariantList = ({
  variants,
  variantsForSelectedDate,
  selectedVariant,
  onClickVariant,
  selectedDateProducts,
  selectedDateOpeningHours,
  variantSummary,
}: VariantListProps) => {
  const variantsForDate = Object.values(variants).filter((variant) => variantsForSelectedDate.includes(variant.id));
  variantsForDate.sort(sortIndexComparer);
  const radioOptions: Array<RadioOption> = variantsForDate.map((variant) => {
    const summary = variantSummary.get(variant.id);
    return {
      value: variant.id,
      label: (
        <VariantListItem
          key={`variant-${variant.id}`}
          variant={variant}
          selectedDateOpeningHours={selectedDateOpeningHours}
          selectedDateProducts={selectedDateProducts}
          variantSummary={summary}
        />
      ),
      disabled: !summary.hasTicketsLeft || hasTimePassed(selectedDateProducts, variant.id),
    };
  });

  const onChangeVariant = (name: string, value: (typeof ENTRY_VARIANT)[keyof typeof ENTRY_VARIANT]) => {
    onClickVariant(variants[value]);
  };

  return (
    <StyledRadioButtons
      options={radioOptions}
      value={selectedVariant}
      name="variant-radio"
      onChange={onChangeVariant}
      displayMode="VERTICAL"
    />
  );
};

export default VariantList;
