import { DateMap } from "@/core/helpers/date-helper";
import { Matcher } from "react-day-picker";

export function withIsSoldOutExceptForEventDays(
  dayInfo: DateMap<{ isSoldOut?: boolean; hasEvents?: boolean }>,
): Record<string, Matcher> {
  return {
    isSoldOut: (day: Date) => {
      const info = dayInfo.get(day);
      if (info?.hasEvents) return false;
      return !!info?.isSoldOut;
    },
  };
}
